function cleanStudyText(v){return String(v||'').replace(/\[[^\]]*(?:image|vectorstock|map)[^\]]*\]/gi,'').replace(/^\s*[+|=-]{5,}.*$/gm,'').replace(/\[\s*\]/g,'').replace(/\n{3,}/g,'\n\n').trim()}
