function quota(i){return course.quotas[i]||0}
function beforeCards(i){return course.levels.slice(0,i).reduce((n,x)=>n+x.cards.length,0)}
function beforeQuestions(i){let n=0;for(let x=0;x<i;x++)n+=quota(x);return n}
function totalCards(){return course.levels.reduce((n,x)=>n+x.cards.length,0)}
function coursePercent(){return Math.round((course.cardsDone+course.answered)/(totalCards()+course.totalQuestions)*100)}
function coursePassMark(){return Math.ceil(course.totalQuestions*.7)}
