function keyWords(text){const stop=new Set('اور میں سے کو کے کی کا ہے ہیں تھا تھی تھے ایک یہ وہ اس پر لئے لیے ساتھ بھی جو تک یا نے جبکہ اگر لیکن بہت اپنے اپنی ان کہ طور بعد بارے ملک'.split(' '));return String(text).replace(/[^\u0600-\u06FFA-Za-z0-9\s-]/g,' ').split(/\s+/).map(x=>x.trim()).filter(x=>x.length>3&&!stop.has(x))}
