function optionSet(answer,candidates){let out=[answer],list=candidates||[],start=list.length?normalized(answer).length%list.length:0;for(let j=0;j<list.length&&out.length<4;j++){let x=list[(start+j)%list.length];if(x&&normalized(x)!==normalized(answer)&&!out.some(y=>normalized(y)===normalized(x)))out.push(x)}for(let t of TOPICS)if(out.length<4&&!out.includes(t.label))out.push(t.label);return shuffle(out.slice(0,4))}
