async function loadCourseProgress(c){course=buildCourse(c);try{let id=viewerId();if(!id)return;let r=await fetch(API_URL+'/rest/v1/culture_learning_progress?user_id=eq.'+encodeURIComponent(id)+'&country_slug=eq.'+encodeURIComponent(c.slug)+'&select=*',{headers:headers()});if(r.ok){let p=(await r.json())[0];if(p){course.level=Math.max(0,Math.min(course.levels.length-1,(p.level_number||1)-1));course.cardsDone=Math.min(totalCards(),p.cards_completed||0);course.answered=Math.min(course.totalQuestions,p.questions_answered||0);course.score=Math.min(course.answered,p.score||0)}}}catch(e){console.warn(e)}}
async function saveCourseProgress(){if(!course)return;let id=viewerId();if(!id)return;let complete=course.answered>=course.totalQuestions,body={user_id:id,country_slug:course.country.slug,user_name:viewerName(),country_name:course.country.name,level_number:Math.min(course.level+1,course.levels.length),cards_completed:course.cardsDone,questions_answered:course.answered,score:course.score,total_questions:course.totalQuestions,progress_percent:coursePercent(),completed:complete,updated_at:new Date().toISOString()};try{let r=await fetch(API_URL+'/rest/v1/culture_learning_progress?on_conflict=user_id,country_slug',{method:'POST',headers:{...headers(),Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(body)});if(!r.ok)console.warn('Culture progress save failed',await r.text())}catch(e){console.warn(e)}}
function progressHead(){let p=coursePercent(),topic=course.levels[course.level].topic;return `<div class="learn-progress"><div class="learn-progress-top"><b>${safe(course.country.name)} · Level ${course.level+1}/${course.levels.length}</b><span>${p}% Complete · Score ${course.score}/${course.answered}</span></div><div class="learn-progress-topic">${topic.icon} ${safe(topic.label)}</div><div class="learn-progress-track"><i style="width:${p}%"></i></div></div>`}
