async function getLanguageData(){if(languageData)return languageData;let r=await fetch(ROOT+'bangla-learning.json',{cache:'no-store'});if(!r.ok)throw Error('Bangla course could not load.');languageData=await r.json();return languageData}
function languageHubPage(){return `<div class="culture"><button class="btn btn-secondary" id="languageBack">← Back to Country Culture</button><section class="culture-hero"><small>LANGUAGES DEPARTMENT · PRACTICAL COMMUNICATION</small><h2>Language Learning Centre</h2><p>Short guided lessons, real-life dialogue, Roman pronunciation, Urdu meanings and evidence-based checkpoints.</p><div class="culture-stats"><span><b>73</b> Bangla Lessons</span><span><b>397</b> Dialogue Lines</span><span><b>100</b> Questions / Marks</span></div></section><div class="language-grid"><article class="language-tile available"><span class="language-badge">AVAILABLE NOW</span><div class="language-native">বাংলা</div><h3>Bangla</h3><small>Bangladesh · Travel, daily conversation and Dawah</small><button class="btn btn-primary language-choice" id="hubBangla" style="margin-top:14px">START / CONTINUE COURSE →</button></article>${[['中文','Chinese'],['العربية','Arabic'],['English','English']].map(x=>`<article class="language-tile"><span class="language-badge">COMING NEXT</span><div class="language-native">${x[0]}</div><h3>${x[1]}</h3><small>The same reusable lesson-and-checkpoint format is ready for future content.</small></article>`).join('')}</div></div>`}
function buildLanguageCourse(data){let expanded=[];(data.lessons||[]).forEach(lesson=>{if(lesson.dialogue?.length){for(let i=0;i<lesson.dialogue.length;i+=4)expanded.push({...lesson,dialogue:lesson.dialogue.slice(i,i+4),part:Math.floor(i/4)+1,parts:Math.ceil(lesson.dialogue.length/4)})}else expanded.push({...lesson,part:1,parts:1})});let levels=[];for(let category of data.categories||[]){let cards=expanded.filter(x=>x.category===category);for(let i=0;i<cards.length;i+=4)levels.push({category,cards:cards.slice(i,i+4)})}return {data,levels,level:0,cardsDone:0,answered:0,score:0,reviewCard:null,introSeen:{},questionCache:{},feedback:null}}
function languageQuota(i){let n=languageCourse.levels.length,base=Math.floor(TOTAL/n),extra=TOTAL%n;return base+(i<extra?1:0)}
function languageBeforeCards(i){return languageCourse.levels.slice(0,i).reduce((n,x)=>n+x.cards.length,0)}
function languageBeforeQuestions(i){let n=0;for(let x=0;x<i;x++)n+=languageQuota(x);return n}
