function languageAllFacts(){return languageCourse.levels.flatMap(l=>l.cards.flatMap(cardFacts)).filter(x=>x.urdu&&x.bangla&&x.roman)}
function languageOptions(answer,values){let out=[answer];for(let v of shuffle(values))if(v&&normalized(v)!==normalized(answer)&&!out.some(x=>normalized(x)===normalized(v)))out.push(v);return shuffle(out.slice(0,4))}
function languageQuestion(levelIndex,localQ){let key=levelIndex+':'+localQ;if(languageCourse.questionCache[key])return languageCourse.questionCache[key];let globalQ=languageBeforeQuestions(levelIndex)+localQ,level=languageCourse.levels[levelIndex],localFacts=level.cards.flatMap(cardFacts).filter(x=>x.urdu&&x.bangla&&x.roman),all=languageAllFacts(),fact=localFacts[globalQ%localFacts.length]||all[globalQ%all.length],type=globalQ%6,x;if(type===0)x={kind:'Meaning Choice',difficulty:'Foundation',source:fact.bangla,sourceClass:'bn',q:'اس بنگلہ جملے یا لفظ کا درست اردو معنی منتخب کریں۔',answer:fact.urdu,options:languageOptions(fact.urdu,all.map(y=>y.urdu))};if(type===1)x={kind:'Bangla Recognition',difficulty:'Applied',source:fact.urdu,sourceClass:'urdu-meaning',q:'اس اردو عبارت کے مطابق درست بنگلہ عبارت منتخب کریں۔',answer:fact.bangla,options:languageOptions(fact.bangla,all.map(y=>y.bangla))};if(type===2)x={kind:'Roman Recognition',difficulty:'Applied',source:fact.roman,sourceClass:'roman-line',q:'اس Roman pronunciation کے مطابق درست بنگلہ عبارت منتخب کریں۔',answer:fact.bangla,options:languageOptions(fact.bangla,all.map(y=>y.bangla))};if(type===3)x={kind:'Written Roman',difficulty:'Challenge',typed:true,source:fact.bangla,sourceClass:'bn',q:'اس بنگلہ عبارت کی Roman pronunciation خود لکھیں۔',answer:fact.roman,options:[]};if(type===4){let other=all.find(y=>normalized(y.urdu)!==normalized(fact.urdu))||fact,correct=Math.floor(globalQ/6)%2===0,pair=correct?fact.urdu:other.urdu;x={kind:'True or False',difficulty:'Challenge',source:fact.bangla,sourceClass:'bn',q:`کیا اس بنگلہ عبارت کا اردو معنی ”${pair}“ ہے؟`,answer:correct?'درست':'غلط',options:shuffle(['درست','غلط'])}}if(type===5){let words=level.cards.flatMap(c=>c.words||[]),word=words[globalQ%Math.max(1,words.length)];if(word)x={kind:'Word Hunt',difficulty:'Challenge',source:word.urdu,sourceClass:'urdu-meaning',q:'سبق کے word breakdown سے درست بنگلہ لفظ تلاش کریں۔',answer:word.bangla,options:languageOptions(word.bangla,all.map(y=>y.bangla))};else x={kind:'Dialogue Search',difficulty:'Challenge',source:fact.urdu,sourceClass:'urdu-meaning',q:'مکالمے میں اس اردو جملے کے لیے درست Roman pronunciation تلاش کریں۔',answer:fact.roman,options:languageOptions(fact.roman,all.map(y=>y.roman))}}languageCourse.questionCache[key]=x;return x}
function languageCardHtml(card){let part=card.parts>1?` · PART ${card.part}/${card.parts}`:'';if(card.words?.length)return `<small>${safe(card.category)} · SENTENCE LESSON${part}</small><h2 class="culture-urdu">${safe(card.title)}</h2><div class="bangla-script" lang="bn">${safe(card.bangla)}</div><div class="roman-line"><b>Roman:</b> ${safe(card.roman)}</div><div class="urdu-meaning">${safe(card.urdu)}</div><div class="word-grid">${card.words.map(w=>`<div class="word-chip"><b lang="bn">${safe(w.bangla)}</b><span>${safe(w.urdu)}</span><small>${safe(w.roman)}</small></div>`).join('')}</div>`;return `<small>${safe(card.category)} · PRACTICAL DIALOGUE${part}</small><h2 class="culture-urdu">${safe(card.title)}</h2>${card.bangla?`<div class="bangla-script" lang="bn">${safe(card.bangla)}</div><div class="roman-line"><b>Roman:</b> ${safe(card.roman)}</div>`:''}<div class="dialogue-list">${card.dialogue.map(x=>`<div class="dialogue-row"><div class="urdu-meaning">${safe(x.urdu)}</div><div class="bangla-script" lang="bn">${safe(x.bangla)}</div><div class="roman-line">${safe(x.roman)}</div></div>`).join('')}</div>`}
function languageProgressHead(){let p=languagePercent(),level=languageCourse.levels[languageCourse.level];return `<div class="learn-progress"><div class="learn-progress-top"><b>🇧🇩 Bangla · Level ${languageCourse.level+1}/${languageCourse.levels.length}</b><span>${p}% Complete · Score ${languageCourse.score}/${languageCourse.answered}</span></div><div class="learn-progress-topic">${safe(level.category)}</div><div class="learn-progress-track"><i style="width:${p}%"></i></div></div>`}
async function loadLanguageProgress(){let data=await getLanguageData();languageCourse=buildLanguageCourse(data);try{let id=viewerId();if(!id)return;let slug='language-'+data.course_slug,r=await fetch(API_URL+'/rest/v1/culture_learning_progress?user_id=eq.'+encodeURIComponent(id)+'&country_slug=eq.'+encodeURIComponent(slug)+'&select=*',{headers:headers()});if(r.ok){let p=(await r.json())[0];if(p){languageCourse.level=Math.max(0,Math.min(languageCourse.levels.length-1,(p.level_number||1)-1));languageCourse.cardsDone=Math.min(languageTotalCards(),p.cards_completed||0);languageCourse.answered=Math.min(TOTAL,p.questions_answered||0);languageCourse.score=Math.min(languageCourse.answered,p.score||0)}}}catch(e){console.warn(e)}}
async function saveLanguageProgress(){if(!languageCourse)return;let id=viewerId();if(!id)return;let data=languageCourse.data,body={user_id:id,country_slug:'language-'+data.course_slug,user_name:viewerName(),country_name:'Bangladesh · Bangla Language',level_number:Math.min(languageCourse.level+1,languageCourse.levels.length),cards_completed:languageCourse.cardsDone,questions_answered:languageCourse.answered,score:languageCourse.score,total_questions:TOTAL,progress_percent:languagePercent(),completed:languageCourse.answered>=TOTAL,updated_at:new Date().toISOString()};try{let r=await fetch(API_URL+'/rest/v1/culture_learning_progress?on_conflict=user_id,country_slug',{method:'POST',headers:{...headers(),Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify(body)});if(!r.ok)console.warn('Language progress save failed',await r.text())}catch(e){console.warn(e)}}
function answerLanguageQuestion(x,value){let correct=x.typed?typedCorrect(x.answer,value):normalized(x.answer)===normalized(value);if(correct)languageCourse.score++;languageCourse.answered++;languageCourse.feedback={correct,answer:x.answer};saveLanguageProgress();renderCulture()}
function renderLanguageCourse(host){let li=languageCourse.level,level=languageCourse.levels[li],cards=level.cards,lc=Math.max(0,languageCourse.cardsDone-languageBeforeCards(li)),lq=Math.max(0,languageCourse.answered-languageBeforeQuestions(li)),questions=languageQuota(li),exit=()=>{saveLanguageProgress();languageCourse=null;languageMode=true;renderCulture()};if(languageCourse.feedback){let f=languageCourse.feedback;host.innerHTML=`<div class="culture learn-shell">${languageProgressHead()}<article class="learn-card feedback-card ${f.correct?'':'wrong'}"><div style="font-size:48px">${f.correct?'✓':'↻'}</div><h2>${f.correct?'Correct Answer':'Review This Answer'}</h2><div class="feedback-answer"><b>Correct answer</b><div class="culture-urdu">${safe(f.answer)}</div></div><button class="btn btn-primary" id="langFeedbackNext">Continue →</button></article></div>`;$('#langFeedbackNext').onclick=()=>{languageCourse.feedback=null;renderCulture()};return}if(languageCourse.answered>=TOTAL){host.innerHTML=`<div class="culture learn-shell">${languageProgressHead()}<div class="level-done"><h2>Bangla Course Completed</h2><h1>${languageCourse.score} / 100</h1><p>${languageCourse.score>=PASS?'Congratulations — Passed':'Review the lessons and improve your score.'}</p><button class="btn btn-primary" id="languageHome">Back to Language Centre</button></div></div>`;$('#languageHome').onclick=exit;return}if(lc===0&&lq===0&&!languageCourse.introSeen[li]){let topics=[...new Set(cards.map(x=>x.title))];host.innerHTML=`<div class="culture learn-shell"><button class="btn btn-secondary" id="languageExit">← Save & Exit</button>${languageProgressHead()}<section class="level-overview"><div class="topic-icon">${li<Math.ceil(25/4)?'💬':'🗣️'}</div><small>LEVEL ${li+1} · WHAT YOU WILL LEARN</small><h2>${safe(level.category)}</h2><p>This level contains ${cards.length} short lesson cards and ${questions} varied knowledge-check questions.</p><ul>${topics.map(x=>`<li class="culture-urdu">${safe(x)}</li>`).join('')}</ul><button class="btn btn-primary" id="beginLanguageLevel">Begin Level →</button></section></div>`;$('#languageExit').onclick=exit;$('#beginLanguageLevel').onclick=()=>{languageCourse.introSeen[li]=true;renderCulture()};return}if(lc<cards.length||languageCourse.reviewCard!==null){let shown=languageCourse.reviewCard===null?lc:languageCourse.reviewCard,card=cards[shown],review=languageCourse.reviewCard!==null;host.innerHTML=`<div class="culture learn-shell"><button class="btn btn-secondary" id="languageExit">← Save & Exit</button>${languageProgressHead()}<article class="learn-card">${languageCardHtml(card)}<div class="learn-actions">${shown>0?'<button class="btn btn-secondary" id="languagePrevious">← Previous Card</button>':'<span></span>'}<button class="btn btn-primary" id="languageNext">${review?'Return to Current Step →':lc===cards.length-1?'Continue to Checkpoint →':'Next Card →'}</button></div></article></div>`;$('#languageExit').onclick=exit;let prev=$('#languagePrevious');if(prev)prev.onclick=()=>{languageCourse.reviewCard=shown-1;renderCulture()};$('#languageNext').onclick=()=>{if(review){if(shown<lc-1)languageCourse.reviewCard=shown+1;else languageCourse.reviewCard=null}else{languageCourse.cardsDone++;saveLanguageProgress()}renderCulture()};return}if(lq<questions){let x=languageQuestion(li,lq),answers=x.typed?`<input class="typed-answer" id="typedLanguageAnswer" placeholder="Write the Roman pronunciation here"><button class="btn btn-primary" id="submitLanguage" style="margin-top:12px">SUBMIT ANSWER →</button>`:x.options.map(o=>`<button class="culture-option culture-urdu" data-language-answer="${safe(o)}">${safe(o)}</button>`).join('');host.innerHTML=`<div class="culture learn-shell"><button class="btn btn-secondary" id="languageExit">← Save & Exit</button>${languageProgressHead()}<article class="learn-card checkpoint"><small>LEVEL ${li+1} CHECKPOINT · QUESTION ${lq+1} OF ${questions} · 1 MARK</small><div class="question-meta"><span class="question-badge">${safe(x.difficulty)}</span><span class="question-badge question-type">${safe(x.kind)}</span></div><h2>Lesson Knowledge Check</h2><div class="question-urdu">${safe(x.q)}</div><div class="language-q-source ${safe(x.sourceClass)}">${safe(x.source)}</div>${answers}<div class="learn-actions"><button class="btn btn-secondary" id="reviewLanguageCards">← Review Lesson Cards</button><span></span></div></article></div>`;$('#languageExit').onclick=exit;$('#reviewLanguageCards').onclick=()=>{languageCourse.reviewCard=cards.length-1;renderCulture()};if(x.typed){let submit=()=>{let v=$('#typedLanguageAnswer').value.trim();if(!v)return alert('Please write your answer first.');answerLanguageQuestion(x,v)};$('#submitLanguage').onclick=submit;$('#typedLanguageAnswer').onkeydown=e=>{if(e.key==='Enter')submit()}}else host.querySelectorAll('[data-language-answer]').forEach(b=>b.onclick=()=>answerLanguageQuestion(x,b.dataset.languageAnswer));return}host.innerHTML=`<div class="culture learn-shell">${languageProgressHead()}<div class="level-done"><h2>Level ${li+1} Completed</h2><p>You completed ${cards.length} lesson cards and ${questions} knowledge-check questions.</p><button class="btn btn-primary" id="nextLanguageLevel">${li===languageCourse.levels.length-1?'Complete Course':'Start Next Level →'}</button></div></div>`;$('#nextLanguageLevel').onclick=()=>{if(li<languageCourse.levels.length-1)languageCourse.level++;else languageCourse.answered=TOTAL;languageCourse.reviewCard=null;saveLanguageProgress();renderCulture()}}
async function resultsPage(){const r=await fetch(API_URL+'/rest/v1/culture_learning_progress?select=user_name,country_name,level_number,cards_completed,questions_answered,score,total_questions,progress_percent,completed,updated_at&order=updated_at.desc&limit=300',{headers:headers()});const rows=r.ok?await r.json():[];return `<div class="culture"><button class="btn btn-secondary" id="resultsBack">← Back</button><section class="culture-hero"><h2>Live Culture Learning Progress</h2><p>Reading cards, assessment progress and scores are updated automatically.</p></section><div class="culture-section" style="overflow:auto"><table class="progress-table" style="width:100%;border-collapse:collapse"><tr><th>User</th><th>Country</th><th>Level</th><th>Cards</th><th>Questions</th><th>Score</th><th>Progress</th><th>Status</th></tr>${rows.map(x=>`<tr><td>${safe(x.user_name)}</td><td>${safe(x.country_name)}</td><td>${x.level_number}</td><td>${x.cards_completed}</td><td>${x.questions_answered}/${x.total_questions||100}</td><td>${x.score}/${x.questions_answered}</td><td>${Math.round(x.progress_percent||0)}%</td><td>${x.completed?(x.score>=Math.ceil((x.total_questions||100)*.7)?'Passed':'Failed'):'In Progress'}</td></tr>`).join('')||'<tr><td colspan="8">No learning activity yet.</td></tr>'}</table></div></div>`}
async function renderCulture(){const host=$('#content');if(!host)return;host.innerHTML='<div class="culture-empty">Loading Learning Centre…</div>';try{let all=await catalogue();if(languageCourse){renderLanguageCourse(host);return}if(languageMode){host.innerHTML=languageHubPage();$('#languageBack').onclick=()=>{languageMode=false;renderCulture()};$('#hubBangla').onclick=async()=>{await loadLanguageProgress();renderCulture()};return}if(course){renderCourse(host);return}if(showResults){host.innerHTML=await resultsPage();$('#resultsBack').onclick=()=>{showResults=false;renderCulture()};return}if(chosen){let c=await getGuide(chosen);if(editing){host.innerHTML=editorPage(c);bindEditor(c);return}host.innerHTML=guidePage(c);$('#cultureBack').onclick=()=>{chosen=null;renderCulture()};$('#cultureTest').onclick=async()=>{await loadCourseProgress(c);renderCulture()};let start=$('#startBangla');if(start)start.onclick=async()=>{await loadLanguageProgress();renderCulture()};let e=$('#cultureEdit');if(e)e.onclick=()=>{editing=true;renderCulture()};return}let q=String(window.cultureSearch||'').toLowerCase(),r=window.cultureRegion||'All',filtered=all.filter(c=>(r==='All'||region(c.name)===r)&&(!q||c.name.toLowerCase().includes(q)||String(c.summary||'').includes(q)));host.innerHTML=home(filtered);$('#openLanguageHub').onclick=()=>{languageMode=true;renderCulture()};$('#cultureSearch').value=window.cultureSearch||'';$('#cultureSearch').oninput=e=>{window.cultureSearch=e.target.value;renderCulture()};$('#cultureClear').onclick=()=>{window.cultureSearch='';renderCulture()};host.querySelectorAll('[data-region]').forEach(b=>b.onclick=()=>{window.cultureRegion=b.dataset.region;renderCulture()});host.querySelectorAll('[data-country]').forEach(b=>b.onclick=()=>{chosen=b.dataset.country;renderCulture()});if(isAdmin()){let b=document.createElement('button');b.className='btn btn-primary';b.textContent='Live Progress Dashboard';$('#cultureClear').after(b);b.onclick=()=>{showResults=true;renderCulture()}}}catch(e){host.innerHTML='<div class="notice">'+safe(e.message)+'</div>'}}
function install(){if(typeof pages==='undefined'||typeof NAV_ADMIN==='undefined'||typeof NAV_MEMBER==='undefined')return setTimeout(install,100);window.cultureRegion='All';addStyle();addLearningStyle();if(typeof cloudPull==='function'&&!window.__cultureCloudGuard){window.__cultureCloudGuard=true;const originalCloudPull=cloudPull;cloudPull=async function(show=false){if(currentPage!=='culture'&&currentPage!=='languages')return originalCloudPull(show);const originalRender=render;render=function(){};try{return await originalCloudPull(show)}finally{render=originalRender}}}if(!NAV_ADMIN.some(x=>x[0]==='culture'))NAV_ADMIN.splice(1,0,['culture','Country Culture','◈']);if(!NAV_MEMBER.some(x=>x[0]==='culture'))NAV_MEMBER.splice(1,0,['culture','Country Culture','◈']);if(!NAV_ADMIN.some(x=>x[0]==='languages'))NAV_ADMIN.splice(2,0,['languages','Language Learning','文']);if(!NAV_MEMBER.some(x=>x[0]==='languages'))NAV_MEMBER.splice(2,0,['languages','Language Learning','文']);pages.culture=()=>{languageMode=false;setTimeout(renderCulture,0);return '<div class="culture-empty">Loading Country Culture…</div>'};pages.languages=()=>{languageMode=true;chosen=null;course=null;setTimeout(renderCulture,0);return '<div class="culture-empty">Loading Language Learning Centre…</div>'};if(typeof session!=='undefined'&&session)renderNav()}
